<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$pw=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)$err='Complete all fields. Password must be at least 8 characters.';else{try{$s=$pdo->prepare("INSERT INTO users(name,email,phone,password,role) VALUES(?,?,?,?,'student')");$s->execute([$name,$email,$phone,password_hash($pw,PASSWORD_DEFAULT)]);notice('Account created. Please sign in.');header('Location: login.php');exit;}catch(PDOException $e){$err='That email is already registered.';}}}layout_start('Create student account');?><section class="auth"><?php if($err):?><p class="error"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Full name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone (optional)<input name="phone"></label><label>Password<input type="password" name="password" minlength="8" required></label><button>Register</button></form><p>Already registered? <a href="login.php">Sign in</a></p></section><?php layout_end();?>